from author_library import *
cards=[]
cards.append(compact('wu_luyuan','伍路元','伍路元少年时贫穷、好学，母亲多病，父亲沉迷赌博。他去找拿着买米钱赌博的父亲，反被重打，冲上马路后遭陈老撞断右腿。陈老因为一场奇梦把他视作救星，送他医治，又在临终前把事业传给这个受悉心栽培的义子。他没有同陈家三子争权，而是取走部分积财离开，判断帮会将被时代淘汰。到海外时，他又因古勒勒梦见救星而卷入独立运动，以与沙利文的旧交保护躲在浴室中的领袖，随后娶其妹妹，在岛上成为极受尊重的家族长者。两次难以解释的巧合使他相信梦能指示命运，也给晚辈留下利用的入口。晚年孙子与王莲合谋，伪造第三场梦，把贪官免死和全族安危同资源合作绑定，他终于同意签约。卫斯理看穿骗局，却不能把他的信任当笑话；正是这位缺腿老人，在卫斯理突然收劲自伤时迅速施救，把人从重伤边缘拉回。他的铁拐本领与判断真实存在，救星传说却不是能随叫随到的命运权柄。','《非常遭遇》救下卫斯理并同意岛国资源合作，未获知第三梦骗局的全部内情','主角','保护家族并回报恩情，理解反复改变自己一生的梦','缓慢而仔细讲述旧事，尊重承诺，对亲人有深厚信任','现场危急时凭老练武术立即救人；涉及家族灾祸时又可能被信任关系牵动','能看清时代大势，不代表能看穿亲属为利益设计的局',[ab('武术与铁拐','长期江湖训练、假腿行走、以铁拐配合力量和技巧行动','跑赢冠军及拐中无穷机关属于传闻，不据此确定速度或暗器清单'),ab('紧急行气救护','准确识别卫斯理收劲自伤，用自身劲力拍按胸背使其脱险','仅为特定武术伤情的及时处理，不能治疗所有疾病或复活死人'),ab('经营与关系判断','理解帮会、政治与家族资源，能够在局势变化时退让或合作','亲人出卖与神秘巧合使其判断存在盲点')],[ev('141',110,140,'贫困、父亲暴力和断腿起源'),ev('141',177,208,'让权、真实训练与传闻边界'),ev('141',597,610,'岛国终局地位'),ev('141',1048,1064,'具体救护表现'),ev('141',1264,1288,'被骗后的协议与家族选择')],profile='martial',aliases=['铁拐五路元帅'],extra={'appearance':{'description':'年长，缺右腿，装有假腿并常持铁拐；少年脸上的五道红印不是终身法印。','portrayal':'叙旧细而慢，急事判断快；拒绝受救者跪谢。'}}))
cards.append(compact('chen_laoshimen','陈老石门','陈老石门是一位从长期杀伐中建立地盘的帮会领袖，称号来自他多年不倒、敌手却屡遭摧折的江湖声望。军阀为了新宠的两个兄长逼他交出地盘，他不能答应，也无法正面同军队抗争，便准备只身赴宴、必要时同归于尽。那一夜他梦见老人，说会有铁拐五路元帅救他；第二天急驶中撞断少年伍路元的腿，看到脸上的五道掌印，他把梦与眼前人联系起来，决定送医并守候手术。这个决定让他错过本来会被伏击的路线，恰逢军阀遭对头袭击垮台，死局随之消失。他相信少年是自己的救星，却不是只把对方当护符；此后栽培伍路元，教他文武本领，最终把事业传给义子而非亲生儿子。其恩情与迷信、器重与依靠相互交织，也引起后代争权。卡片以生前行动者为部署，承认他后来已经死亡；一场梦改变了选择，并没有证明他会施法或必得天意保护。江湖威势依赖真实追随者，不会随着复原身体自动恢复整片地盘。','《非常遭遇》的历史人物，已自然离世并把事业传给伍路元；部署需恢复生前人身','主角','维护帮会、兑现对认定恩人的信任，同时保住自己的尊严','面对强权先保持镇定，暗中考虑最坏结果','被逼背弃兄弟时宁愿冒险赴死，认定救星后又倾尽心力扶持','选择一旦建立于深刻信念，会把承诺贯彻多年',[ab('老练江湖武术','经历杀伐，能跃出未停稳车辆并空翻落地','没有已证实能独自击败正规军的能力'),ab('组织经营与传承','积累帮会势力、培养接班人、与外部军政关系周旋','势力依赖部众和时代，死亡后不随个人恢复')],[ev('141',21,48,'帮会身份与军阀逼迫'),ev('141',61,95,'跳车、救人和医治'),ev('141',155,180,'脱险及传位后果')],profile='martial',aliases=['陈老'],extra={'adaptations':[{'change':'恢复最后生前可行动形态，保留伍路元后来选择的终局知识。','reason':'原作已亡，需要明确互动接口。','power_impact':'不恢复整套帮会势力，不授予预言或命运保护。'}]}))
cards.append(compact('gu_lele','古勒勒','古勒勒是海岛独立运动的领袖，在法国殖民者眼中又是必须抓住的头号通缉者。他在山区建立组织，能够鼓舞追随者继续争取独立，因而自己的自由既关乎个人性命，也影响整个运动的信心。一次必须进入城市执行的任务让他身陷搜捕，梦中的老人却指示他去寻找五路元帅。他在旅馆里等到陌生的伍路元，确认对方只有一条腿后，几乎把全部希望交给这个救星。这份相信使他在危险中能够镇定，却没有凭空产生脱身法术；真正改变局面的，是伍路元与沙利文恰好重逢，和随后国际形势的转变。他在浴室藏了两天，禁令撤销，身份由通缉犯变成民族英雄。独立后他成为首任总统，受到国际尊重，也感激伍路元，邀请其入仕并让妹妹招待他，促成了新的家族关系。终局所见的是一个完成政治使命并留下影响的领袖，没有明确交代其个人寿命；梦只是经历，他不能主动向别人发放同样可靠的神谕，家族政权也不等于他的肉体攻击力。','《非常遭遇》历史线完成独立并成为首任总统，个人晚年生死未交代','主角','实现海岛独立，保住运动的延续并报答帮助者','在危局中保持政治目标，主动请求可能的援助','搜捕逼近时凭梦认定救星，能暂时把控制权交给帮助者','信任有时带来生路，但具体结果仍由人际与现实条件共同造成',[ab('政治领导','组织独立运动并维持追随者信心，独立后治理国家','社会影响不作攻击面积，不能直接命令异世界所有人'),ab('隐蔽与求助','在追捕中进入旅馆藏匿并识别援手机会','曾极接近被发现，未显示绝对隐身或预知')],[ev('141',421,455,'独立运动地位与求助'),ev('141',589,608,'躲藏、独立与总统结局'),ev('141',613,620,'梦中指示为事件而非自身施法')],profile='ordinary'))
cards.append(compact('sha_liwen','沙利文','沙利文起初是租界警局的低级警官，不想做清官，与伍路元以好处和便利互相扶持。敌对势力为了切断伍路元的警界靠山，将他装进绑着铅块的帆布袋准备沉江；伍路元和偶然经过的范高头救回了他，他又立刻调人反击，借对方庆功时出其不意地捕杀，官阶由此上升。两人后来结拜，分离以后沙利文进入国防与军队，终于成为海岛军法统治的最高人物。此时他奉殖民统治目标围捕独立领袖古勒勒，甚至准备搜不到人就疏散旅馆再炸毁整座建筑。重逢旧友让搜捕暂时退让，正好掩护了藏在伍路元浴室中的目标；国际局势变化后，他调回法国，失去继续追捕的政治条件。这个人物对朋友真切感恩，却能以机构权力对付陌生人和政治敌人，两种行为并不互相抵消。终局卡保留他的人脉、军警经验和恩义偏向，不把曾指挥的军队全数转成个人常驻武装，也不因为救命友情就把殖民镇压改写为无害误会。','《非常遭遇》海岛独立后调回法国，军警政治身份随现实任命变化','反派','履行所属权力体系的任务，也强烈维护私人恩义','在警政和江湖之间交换便利，与信任者亲密直接','涉及旧友安全时可以打断既定程序，对政治目标则采取强硬包围措施','他把公权任务与私人感恩分开对待，造成明显双重尺度',[ab('军警组织与行动经验','组织搜捕、部署兵力、掌握管区命令流程','只能指挥实际获授权的部队，不能跨世界自动召军'),ab('人际互惠','长期记得救命恩情，凭旧关系改变现场处理','容易被亲密关系遮蔽任务目标，无法全知部下所见')],[ev('141',531,581,'腐败互惠、沉江获救及仕途'),ev('141',509,529,'重逢时叫停紧张局面'),ev('141',589,599,'围捕计划及调回法国')],profile='investigator',aliases=['沙利文将军','沙利文警官']))
cards.append(compact('wu_minister','伍路元的部长孙子','伍路元的孙子是海岛国的经济部长，年轻而自信，能用带法国口音的英语面对各国代表，也因在上海留学说得一口上海话。他借外祖辈般显赫家族的地位处理国家事务，起初以安排祖父拜访卫斯理的方式出现，看起来是尽心的晚辈。真正的冲突在于资源合作：祖父的反对足以挡住放射性元素开采协议，而他与王莲希望取得同意。两人利用祖父一生受到奇梦影响的经历，构造第三个梦的叙事，把一个高官免死、家族免灾和签署协议绑成一体。他劝祖父别再求问卫斯理，危急时又及时提出“立功”通道，最终让协议快速签订。小说并未明确他有杀祖父的意图，卫斯理的分析也把这种极端可能保留为猜测；确定的是，他利用祖父对亲属的信任，使其在不完整信息下作了重大选择。终局他仍拥有政治位置并完成合作，卡片应以组织渠道、语言和家庭影响表现其能力，不把年轻官位当战斗威力，也不给他真正托梦或支配命运的术法。','《非常遭遇》与王莲完成资源合作协议；祖父未被告知整个骗局','反派','推动岛国资源合作，绕过家族长者的反对','在外交场合自信流畅，在祖父面前借熟悉关系引导谈话','计划可能被外人看穿时催促离开，并迅速提出看似两全的解决办法','把结果和政治利益放在祖父的知情选择之前',[ab('多语外交与家族影响','以部长身份、语言能力和亲属信任促成协议','依赖真实职权与合作者，不能代替祖父作任何无授权决定')],[ev('141',215,222,'部长身份与外貌语言'),ev('141',604,610,'家族关系与上海留学'),ev('141',1215,1279,'与王莲合作及完成协议')],profile='expert',aliases=['部长先生']))
cards.append(compact('chen_warlord','设宴逼迫陈老的军阀','这个未具名的军阀与陈老长期维持互利关系，帮会在他的势力范围内经营，他也借此获得地方支持。娶了新宠之后，他要替对方的两个兄长扩张地位，便逐渐向陈老施压。表面的邀请是让对方独自到新公馆赴宴，似乎还有谈判余地，实际却在必经路线上埋伏一个连，由那两名兄长率领，准备先解决陈老再接收地盘。陈老被迫在屈服和反抗中选择，原以为最多到场被逼交权，后来才知道自己的估计还低估了这份杀心。计划没有等到目标，伍路元受伤带来的耽搁使陈老改变路线；军阀的其他敌人又联络内应发动攻击，他在突袭中溃败逃走，两名执行者也死于救援途中。他的存在说明所谓牢固的权势仍依赖部属和时机，不能把掌兵者的自信当作预知或必胜。终局卡采用败逃的人类将领状态，军队已经瓦解，不再自动附带原驻防连队；他仍可能寻找新靠山、重整关系，但这必须在新场景里实际争取。','《非常遭遇》旧事中遭内外合击败逃，下落不明，原部队四散','反派','以兵权夺取利益并满足亲属关系的要求','用表面礼遇掩饰胁迫，令部下在对方无备时执行计划','遇到阻力时更倾向伏击而非平等谈判；局势突变则先逃生','相信力量能保证交易，却会忽视自己的敌人与部下也有打算',[ab('军权胁迫与伏击安排','利用驻军、路线和宴请制造优势','终局原军队溃散，所有兵力需要重新招募或取得指挥权')],[ev('141',30,48,'逼迫陈老交权的起因'),ev('141',155,170,'溃败、伏击真相与亲属之死')],profile='investigator'))
cards.append(compact('chen_inlaws','军阀新宠的两个兄长','这两名没有分别具名的兄长原本只是陈老手下很小的江湖人物，连亲见领袖的机会也少。妹妹成为军阀新宠之后，他们突然拥有越过帮会常规的外部靠山，立刻来要求提拔。陈老为顾全关系已经给出超出规矩的位置，他们却仍不满足、不去到职，希望借军队直接取代原有秩序。军阀于是安排以宴请诱陈老出门，他们率一个连埋伏在必经路上，承担把私人裙带欲望变成具体暴力的工作。计划因为陈老救护伍路元而落空，等不到目标的他们又获知军阀遭袭，便带兵赶去救自己的靠山，最终全军覆没，两人死在乱军之中。原文没有区分两人的独立习性或分配不同本领，因此用共同人物组记录，不虚构谁更聪明、谁更凶狠。若部署，需要恢复各自最后生前人身并保留失败记忆；原来的连队不随复原获得。他们的弱点是把从亲属关系借来的权势误当自己的能力，判断局势时离不开靠山是否仍在。','《非常遭遇》旧事中两人均战死；部署恢复各自生前最后可行动状态，无原连队','反派','借妹妹与军阀的关系迅速取得地位','用新靠山压过旧组织规矩，以客气口吻提出过分要求','既得利益受威胁时急于保护靠山，可能忽略现场兵力与形势','依赖外部权力上升，个人组织能力未得到证明',[ab('凭靠山调动小部队','在具体授权下率军伏击并救援','群体共用一支历史连队，终局已覆没；无独立超常武力')],[ev('141',39,43,'小人物借姻亲上位'),ev('141',155,170,'伏击任务和战死')],profile='ordinary',extra={'adaptations':[{'change':'部署时恢复两人最后生前人身，仍作为无法区分的共同条目。','reason':'原文没有足够独立信息却有明确共同反派行动。','power_impact':'不赋予额外部队、独立特殊技能或免死效果。'}]}))
cards.append(compact('chen_three_sons','陈老石门的三个儿子','陈老的三个亲生儿子看着父亲长期信任伍路元，认为本应属于自己的权力被外来的义子占据。他们在父亲生前不敢发作，暗中培植势力，等到丧事准备在灵堂上向继承事业的伍路元施压。这不是三个各有完整人物线的角色，文本没有区分姓名和独有手段；共同的动机是以血缘为继承正当性，至少从现任领袖手中分出部分控制权。伍路元却在他们发难前主动让出全部权力，只取十分之一积财，使预想的血斗突然不再必要。他临走认真劝三人认清时代变化、见好就收，他们却无法理解，把警告当作不相干的话。白老大后来也劝过几次，同样不欢而散。故事把他们留在即将衰落的帮会秩序中，没有逐一交代具体死法，卡片不能补出三场报应。终局以已经接手而识见受限的继承人组呈现，不把父亲全部武术和威望遗传给他们；场景中的冲突应来自权利感、竞争和对变化的否认，而非三个机械复制的坏人声音。','《非常遭遇》旧史中接管帮会，拒绝退场警告；个人最终生死未逐一交代','阶段性对立者','保住认为应由血缘继承的权力','暗中联合、争取长辈支持，避免父亲在世时公开冲突','继承受到威胁时准备集体施压，得到权力后不愿听取退出建议','将眼前权位看作可以长期延续的家产，难接受时代正在改变',[ab('继承与内部结盟','借家族关系和已培植的势力争取帮会控制权','三人没有分别展示父亲或伍路元的高超武术，不照搬继承其能力')],[ev('141',177,189,'发难计划、让权及拒绝警告'),ev('141',192,196,'白老大继续劝说而不欢而散')],profile='ordinary'))
save(cards)
